public class Drill {
    static int digitSum(String s) {
        int sum = 0;
        for (char c : s.toCharArray()) {
            if (!Character.isDigit(c)) continue;
            sum += c - '0';
        }
        return sum;
    }
    static int letters(String s) {
        int n = 0;
        for (char c : s.toCharArray()) {
            if (Character.isLetter(c)) n++;
        }
        return n;
    }
    static int alnum(String s) {
        int n = 0;
        for (char c : s.toCharArray()) {
            if (Character.isLetterOrDigit(c)) n++;
        }
        return n;
    }
    static int uppers(String s) {
        int n = 0;
        for (char c : s.toCharArray()) {
            if (Character.isUpperCase(c)) n++;
        }
        return n;
    }
    static char lower(char c) {
        return Character.toLowerCase(c);
    }
    static int sevenValue() {
        return Character.getNumericValue('7');
    }
    static char next(char c) {
        return (char) (c + 1);
    }
    static int slot(char c) {
        @@BLANK@@
    }

    static int bad = 0;
    static void check(Object got, Object exp) {
        String g = String.valueOf(got), e = String.valueOf(exp);
        if (!g.equals(e)) { bad++; System.out.println("FAIL: got " + g + " expected " + e); }
    }
    static void done() { if (bad == 0) System.out.println("PASS"); }

    public static void main(String[] args) {
        check(digitSum("a1b2c3"), 6);
        check(letters("a1b2c3"), 3);
        check(alnum("a-1!"), 2);
        check(uppers("aBcD"), 2);
        check(lower('Q'), 'q');
        check(sevenValue(), 7);
        check(next('a'), 'b');
        check(slot('d'), 3);
        done();
    }
}
